#include "espm_web.h"
#include "espm_config.h"

#include <esp_log.h>
#include <esp_ota_ops.h>

static const char *TAG = "mesp_ota";

static esp_err_t ota_handler(httpd_req_t *req)
{
    if (!mesp_web_authorized(req)) return ESP_OK;
    const esp_partition_t *target = esp_ota_get_next_update_partition(nullptr);
    if (!target) {
        return mesp_web_send_error(req, "500 Internal Server Error", "no OTA partition");
    }
    if (req->content_len > target->size) {
        return mesp_web_send_error(req, "413 Payload Too Large", "image larger than OTA partition");
    }
    esp_ota_handle_t handle;
    esp_err_t err = esp_ota_begin(target, OTA_SIZE_UNKNOWN, &handle);
    if (err != ESP_OK) {
        return mesp_web_send_error(req, "500 Internal Server Error", esp_err_to_name(err));
    }
    ESP_LOGI(TAG, "writing %u bytes to %s", (unsigned)req->content_len, target->label);

    char *buf = (char *)malloc(4096);
    size_t remaining = req->content_len;
    while (remaining > 0) {
        int r = httpd_req_recv(req, buf, remaining < 4096 ? remaining : 4096);
        if (r == HTTPD_SOCK_ERR_TIMEOUT) continue;
        if (r <= 0) {
            free(buf);
            esp_ota_abort(handle);
            return mesp_web_send_error(req, "400 Bad Request", "upload interrupted");
        }
        err = esp_ota_write(handle, buf, r);
        if (err != ESP_OK) {
            free(buf);
            esp_ota_abort(handle);
            return mesp_web_send_error(req, "500 Internal Server Error", esp_err_to_name(err));
        }
        remaining -= r;
    }
    free(buf);

    err = esp_ota_end(handle);
    if (err == ESP_OK) err = esp_ota_set_boot_partition(target);
    if (err != ESP_OK) {
        return mesp_web_send_error(req, "500 Internal Server Error", esp_err_to_name(err));
    }
    ESP_LOGI(TAG, "success, rebooting");
    mesp_restart_soon();
    return mesp_web_send_json(req, "{\"ok\":true}");
}

void mesp_ota_register_web()
{
    mesp_web_add("/api/ota", HTTP_POST, ota_handler);
}
